# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe "Billing fence on invoice and payment routes", type: :request do
  # "Every invoice, line-item, invoice-tax and payment write, mobile-collection payments included,
  # gets 503 ownership_moving while handoff_step is set and writes nothing"
  it "answers invoice create with 503 ownership_moving and Retry-After and writes no invoice during a handoff" do
    company = create(:company)
    client = create(:client, company:)
    user = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user:)
    user.add_role :admin, company
    sign_in user
    TimekeepingOwnership.current.update!(handoff_step: "close_admission")
    invoice = attributes_for(:invoice, invoice_number: "FENCE-CREATE-1", client_id: client.id)

    expect {
      send_request :post, api_v1_invoices_path(invoice:), headers: auth_headers(user)
    }.to not_change(Invoice, :count).and not_change(InvoiceLineItem, :count).and not_change(InvoiceTax, :count)

    expect(response).to have_http_status(:service_unavailable)
    expect(json_response["reason"]).to eq("ownership_moving")
    expect(json_response["errors"]).to be_present
    expect(response.body).not_to include("close_admission")
    expect(response.headers["Retry-After"]).to eq("5")
  end
end

RSpec.describe "Billing fence on invoice discard", type: :request do
  # "Every invoice, line-item, invoice-tax and payment write, mobile-collection payments included,
  # gets 503 ownership_moving while handoff_step is set and writes nothing"
  it "answers invoice discard with 503 ownership_moving and leaves the invoice kept during a handoff" do
    company = create(:company)
    client = create(:client, company:)
    user = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user:)
    user.add_role :admin, company
    sign_in user
    invoice = create(:invoice, company:, client:)
    TimekeepingOwnership.current.update!(handoff_step: "settle")

    send_request :delete, api_v1_invoice_path(invoice), headers: auth_headers(user)

    expect(response).to have_http_status(:service_unavailable)
    expect(json_response["reason"]).to eq("ownership_moving")
    expect(invoice.reload.discarded_at).to be_nil
  end
end

RSpec.describe "Billing fence on invoice update", type: :request do
  # "Every invoice, line-item, invoice-tax and payment write, mobile-collection payments included, gets 503 ownership_moving while handoff_step is set and writes nothing"
  it "answers invoice update with nested line items with 503 ownership_moving and leaves the money unchanged during a handoff" do
    company = create(:company)
    client = create(:client, company:)
    user = create(:user, current_workspace_id: company.id)
    create(:employment, company:, user:)
    user.add_role :admin, company
    sign_in user
    invoice = create(:invoice, company:, client:, invoice_number: "INV-FENCE-1")
    line_item = create(:invoice_line_item, invoice:, timesheet_entry: nil, name: "Work", description: "Work", rate: 100, quantity: 60)
    invoice.reload
    money_before = [invoice.amount, invoice.tax, invoice.discount, invoice.outstanding_amount, line_item.reload.rate, line_item.quantity]
    expect(money_before[4]).to eq(100)

    TimekeepingOwnership.where(id: TimekeepingOwnership::SINGLETON_ID).update_all(handoff_step: "close_admission")

    send_request :patch, api_v1_invoice_path(invoice), params: {
      invoice: {
        client_id: client.id,
        invoice_number: "INV-FENCE-1",
        issue_date: invoice.issue_date.iso8601,
        due_date: invoice.due_date.iso8601,
        currency: invoice.currency,
        invoice_line_items_attributes: [
          { id: line_item.id, name: "Work", description: "Work", date: line_item.date.iso8601, rate: 500, quantity: 120 },
          { name: "Extra", description: "Extra", date: Date.current.iso8601, rate: 50, quantity: 60 }
        ]
      }
    }, headers: auth_headers(user)

    expect(response).to have_http_status(503)
    expect(json_response["reason"]).to eq("ownership_moving")
    expect(json_response.to_s).not_to include("close_admission")
    invoice.reload
    expect([invoice.amount, invoice.tax, invoice.discount, invoice.outstanding_amount, line_item.reload.rate, line_item.quantity]).to eq(money_before)
    expect(invoice.invoice_line_items.count).to eq(1)
  end
end
